import { Cell, Pie, PieChart, ResponsiveContainer, Sector, Tooltip as RechartsTooltip } from "recharts";
import { cn } from "@registry/aikoz/lib/utils";
import {
  ChartFrame,
  ChartTooltipContent,
  opaciteSerie,
  couleurSerie,
} from "@registry/aikoz/chart-frame/chart-frame";
import { type TableColumn } from "@registry/aikoz/table/table";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface DonutPart {
  key: string;
  label: string;
  value: number;
}

export interface DonutChartProps {
  caption: string;
  parts: DonutPart[];
  /** Chiffre au centre — un total, une part dominante. */
  centerValue?: string;
  centerLabel?: string;
  formatValue?: (v: number) => string;
  height?: number;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Anneau de répartition — transposé du `SourcesDonut` des maquettes.
 *
 * **Un anneau se lit mal, et il faut le savoir avant d'en poser un.** L'œil
 * compare des longueurs bien mieux que des angles : au-delà de quatre ou
 * cinq parts, ou dès que deux parts sont proches, une barre horizontale
 * renseigne davantage. L'anneau garde un avantage réel — il montre qu'on
 * regarde un TOUT — d'où le chiffre au centre, qui est souvent la seule
 * information que le lecteur retiendra.
 *
 * Chaque part porte donc **son pourcentage écrit**, en plus de la trame et
 * de la couleur. C'est le seul moyen de comparer deux parts voisines sans
 * les mesurer à l'œil.
 *
 * Le reste du contrat vient de `ChartFrame` : anneau masqué, tableau comme
 * contenu, aucune animation.
 */
export function DonutChart({
  caption,
  parts,
  centerValue,
  centerLabel,
  formatValue = (v) => String(v),
  height = 260,
  className,
}: DonutChartProps) {
  const total = parts.reduce((t, p) => t + p.value, 0);
  const pct = (v: number) => (total ? Math.round((v / total) * 100) : 0);

  const columns: TableColumn<DonutPart>[] = [
    { key: "label", header: "Source" },
    { key: "value", header: "Volume", numeric: true, cell: (p) => formatValue(p.value) },
    { key: "part", header: "Part", numeric: true, cell: (p) => `${pct(p.value)} %` },
  ];

  const resume =
    `${caption}. ${parts.length} parts, total ${formatValue(total)}. ` +
    parts.map((p) => `${p.label} ${pct(p.value)} %`).join(", ") + ".";

  return (
    <ChartFrame
      caption={caption}
      summary={resume}
      series={parts.map((p) => ({ key: p.key, label: `${p.label} · ${pct(p.value)} %` }))}
      data={parts}
      columns={columns}
      getRowKey={(p) => p.key}
      rowHeaderKey="label"
      height={height}
      legendStyle="aplat"
      className={className}
    >
      {({ infobulleActive, indexActif, surSurvol }) => (
        <div className="relative h-full w-full">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart
            // `tabIndex={-1}` : recharts rend son SVG focusable par défaut.
            // Dans un sous-arbre `aria-hidden`, un élément focusable est une
            // contradiction — axe la signale (aria-hidden-focus), et c'en est
            // une vraie : le focus y entrerait sans que rien ne soit annoncé.
            tabIndex={-1}
            style={{ cursor: "pointer" }}
            >
              {infobulleActive && (
                <RechartsTooltip
                  content={
                    <ChartTooltipContent
                      formatValue={(v) =>
                        `${formatValue(Number(v))} · ${pct(Number(v))} %`
                      }
                    />
                  }
                  isAnimationActive={false}
                />
              )}
              <Pie
                data={parts}
                dataKey="value"
                nameKey="label"
                innerRadius="58%"
                outerRadius="88%"
                // Le trait à la couleur de la carte sépare deux parts de
                // teintes voisines, que la palette produira forcément.
                stroke="var(--card)"
                strokeWidth={2}
                isAnimationActive={false}
                // La part pointée s'écarte de 6px vers l'extérieur. C'est le
                // geste que font tous les anneaux modernes, et il fonctionne
                // ici pour une raison précise : sur un cercle, une part fine
                // ne peut pas s'agrandir en largeur — le seul axe disponible
                // est le rayon.
                activeIndex={indexActif ?? undefined}
                activeShape={(p: unknown) => {
                  const s = p as { outerRadius: number };
                  return <Sector {...s} outerRadius={s.outerRadius + 6} />;
                }}
                // Ce calque est RECOUVERT par celui des trames : il ne reçoit
                // jamais le pointeur. Le survol et l'infobulle sont donc
                // portés par le calque du dessus, pas ici.
                tooltipType="none"
                // `rootTabIndex` et non `tabIndex` : recharts pose lui-même
                // `tabindex="0"` sur le groupe racine du `<Pie>` et ignore un
                // `tabIndex` passé en prop. Le sous-arbre est masqué, un
                // élément focusable dedans est une contradiction — axe la
                // signale, et c'en est une vraie : le focus y entrerait sans
                // que rien ne soit annoncé.
                rootTabIndex={-1}
              >
                {parts.map((p, i) => (
                  <Cell
                    key={p.key}
                    fill={couleurSerie(i)}
                    fillOpacity={opaciteSerie(indexActif, i)}
                  />
                ))}
              </Pie>
              {/* Calque transparent posé par-dessus : il ne peint rien, il
                  capte le pointeur et porte le contour d'emphase. Il portait
                  autrefois la trame ; celle-ci a été retirée, la couleur
                  suffisant jusqu'à cinq parts (cf. `ChartFrame`). */}
              <Pie
                data={parts}
                dataKey="value"
                innerRadius="58%"
                outerRadius="88%"
                stroke="none"
                isAnimationActive={false}
                rootTabIndex={-1}
                // `nameKey` : c'est CE calque qui alimente l'infobulle, donc
                // c'est lui qui doit savoir nommer les parts. Sans lui,
                // l'infobulle affichait « 1 : 318 » — l'index de la part à la
                // place de son libellé.
                nameKey="label"
                onMouseEnter={(_, index) => surSurvol({ activeTooltipIndex: index })}
                onMouseLeave={() => surSurvol(null)}
              >
                {parts.map((p, i) => (
                  <Cell
                    key={p.key}
                    fill="transparent"
                  />
                ))}
              </Pie>
            </PieChart>
          </ResponsiveContainer>

          {(centerValue || centerLabel) && (
            <div
              aria-hidden="true"
              className={cn(
                "pointer-events-none absolute inset-0",
                "flex flex-col items-center justify-center text-center"
              )}
            >
              {centerValue && (
                <span className="text-2xl font-bold tabular-nums text-foreground">
                  {centerValue}
                </span>
              )}
              {centerLabel && (
                <span className="text-xs text-muted-foreground">{centerLabel}</span>
              )}
            </div>
          )}
        </div>
      )}
    </ChartFrame>
  );
}

import { useEffect, useId, useState, type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Table, type TableColumn } from "@registry/aikoz/table/table";

// ─── Vocabulaire des séries ──────────────────────────────────────────────────

/**
 * Six séries, trois canaux redondants chacune, dans un ordre FIXE : la
 * série 1 aura toujours le même trait plein et le même rond, quel que soit
 * le graphique. Une identité qui change d'un écran à l'autre ne s'apprend
 * pas.
 *
 * **Le pointillé n'est pas décoratif — la trame, elle, a été retirée.** Mesuré sur notre
 * palette : la meilleure séparation atteignable entre six séries est de
 * **1,26:1 en clair, 1,30 en sombre** — un ratio de LUMINANCE, pas un écart
 * perceptuel. Elles se confondent donc en niveaux
 * de gris et pour une part des daltonismes. La couleur ne porte pas la
 * distinction — elle la renforce, pour qui la perçoit.
 *
 * **Correction d'une mesure fausse.** Ce commentaire disait que la couleur
 * n'avait « aucun pouvoir distinctif », sur la foi d'un ratio de contraste
 * WCAG entre séries. C'était la mauvaise métrique : le ratio WCAG mesure une
 * LUMINANCE, il sert à lire du texte sur un fond, pas à distinguer deux
 * aplats voisins. La bonne mesure est l'écart perceptuel (ΔE OKLab), évalué
 * en simulant les trois daltonismes.
 *
 * Mesuré ainsi, la palette sépare de **ΔE 0,19 à 0,28** en vision normale
 * comme en protanopie et en deutéranopie — très au-dessus du seuil de ~0,10.
 * La couleur suffit donc, et les trames qui hachuraient les barres ont été
 * retirées : elles alourdissaient la lecture sans rien apporter.
 *
 * **Une exception, assumée :** en tritanopie, bleu et vert virent tous deux au
 * turquoise et l'écart tombe à 0,068. Elle touche une personne sur dix mille,
 * contre près de 8 % des hommes pour la deutéranopie, et le tableau sous le
 * graphique porte la donnée sans dépendre d'aucune couleur.
 *
 * Le POINTILLÉ des courbes reste, lui : deux courbes se superposent là où
 * deux barres ne se touchent que par un bord, et les styles de trait sont la
 * recommandation constante de la littérature (Carbon, Datawrapper).
 *
 * Les couleurs de statut restent exclues — une série qui porte le jaune
 * d'avertissement se lit comme une alerte.
 */
export const SERIES = [
  { trait: undefined, nom: "trait plein" },
  { trait: "8 4", nom: "tirets longs" },
  { trait: "2 3", nom: "pointillé fin" },
  { trait: "12 3 2 3", nom: "tiret-point" },
  { trait: "4 4", nom: "tirets courts" },
  { trait: "1 5", nom: "points espacés" },
] as const;

export const couleurSerie = (i: number) => `var(--chart-${(i % 6) + 1})`;
export const styleSerie = (i: number) => SERIES[i % SERIES.length];

// ─── Survol ───────────────────────────────────────────────────────────────────

export interface ContexteGraphique {
  /** Identifiant unique, dérivé de `useId`. */
  idTrames: string;
  /**
   * Faut-il rendre l'infobulle ? Faux quand le pointeur est ailleurs, et faux
   * aussi après un appui sur Échap — cf. `ChartFrame`.
   */
  infobulleActive: boolean;
  /** Index de la catégorie survolée, ou `null`. Sert à l'emphase. */
  indexActif: number | null;
  /** À brancher sur le graphique recharts pour suivre la catégorie survolée. */
  surSurvol: (etat: { activeTooltipIndex?: number | null } | null) => void;
}

/**
 * Emphase de la valeur survolée — **par retrait, pas par ajout**.
 *
 * L'élément pointé ne change pas : ce sont les autres qui s'effacent à 30 %.
 * C'est le geste de Carbon, et il vaut mieux que ce qu'on avait — un contour
 * `--foreground` de 2px, qui lisait comme une SÉLECTION et non comme un
 * survol, et qui ajoutait un trait là où l'œil cherchait une donnée.
 *
 * **J'avais écarté l'atténuation pour une mauvaise raison** : la crainte que
 * les séries estompées tombent sous les 3:1 de WCAG 1.4.11. Ce seuil vaut
 * pour l'état au repos, celui qui permet d'identifier un composant. Une
 * atténuation de survol est transitoire, réversible au moindre mouvement, et
 * n'enlève aucune information — le tableau porte toutes les valeurs. Carbon,
 * Ant Design et Material appliquent tous ce geste.
 *
 * 30 % est la valeur de Carbon. Plus haut, l'effacement ne se voit pas ;
 * plus bas, les autres séries disparaissent au lieu de passer au second plan.
 */
export const OPACITE_ESTOMPEE = 0.3;

/**
 * Opacité d'une série selon ce qui est survolé. `1` quand rien ne l'est —
 * un graphique au repos ne doit jamais être à demi effacé.
 */
export function opaciteSerie(indexActif: number | null, index: number): number {
  return indexActif === null || indexActif === index ? 1 : OPACITE_ESTOMPEE;
}

export interface LigneInfobulle {
  dataKey?: string | number;
  name?: string;
  value?: string | number;
  color?: string;
}

/**
 * Contenu d'infobulle commun aux trois graphiques.
 *
 * Reprend les tokens de `Tooltip` (`--popover`, `--popover-foreground`,
 * `--border-strong`) : une infobulle est une surface flottante comme une
 * autre, et une inversion figée sur `--foreground` casserait le thème.
 *
 * **Elle n'est jamais la seule source d'une valeur** — le tableau qui suit le
 * graphique les porte toutes. C'est ce qui la rend acceptable alors qu'elle
 * ne s'ouvre qu'à la souris.
 */
export function ChartTooltipContent({
  active,
  label,
  payload,
  formatValue = (v) => String(v),
}: {
  active?: boolean;
  label?: string | number;
  payload?: LigneInfobulle[];
  formatValue?: (v: string | number) => string;
}) {
  if (!active || !payload?.length) return null;
  return (
    <div
      className={cn(
        "rounded-[var(--radius)] border border-[var(--border-strong)] px-3 py-2 shadow-lg",
        "bg-[var(--popover)] text-[var(--popover-foreground)] text-xs leading-snug"
      )}
    >
      {label !== undefined && label !== "" && (
        <p className="m-0 mb-1.5 font-semibold">{label}</p>
      )}
      <ul className="m-0 flex list-none flex-col gap-1 p-0">
        {payload.map((p, i) => (
          <li key={String(p.dataKey ?? i)} className="flex items-center gap-1.5">
            <span
              aria-hidden="true"
              className="inline-block size-2.5 shrink-0 rounded-sm"
              style={{ background: p.color }}
            />
            <span>
              {p.name} : <strong className="tabular-nums">{formatValue(p.value ?? "")}</strong>
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ChartSerie {
  key: string;
  label: string;
}

export interface ChartFrameProps<T> {
  /**
   * Ce que le graphique montre — **obligatoire**. C'est la légende du
   * tableau équivalent, donc le nom accessible de la donnée.
   */
  caption: string;
  /** Phrase de résumé. Complétée automatiquement par le renvoi au tableau. */
  summary: string;
  series: ChartSerie[];
  /** Données brutes, telles qu'elles alimentent le tableau équivalent. */
  data: T[];
  /** Colonnes du tableau équivalent. */
  columns: TableColumn<T>[];
  getRowKey: (row: T, index: number) => string;
  /** Colonne qui NOMME la ligne — cf. `Table`. */
  rowHeaderKey?: string;
  /** Le graphique lui-même. Voir `ContexteGraphique`. */
  children: (ctx: ContexteGraphique) => ReactNode;
  height?: number;
  /** Masque la légende, quand le graphique étiquette déjà ses parts. */
  hideLegend?: boolean;
  /** Aplats plutôt que tracés : la légende montre des pastilles pleines. */
  legendStyle?: "trait" | "aplat";
  tableCollapsed?: boolean;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Coque commune à tous les graphiques.
 *
 * **Pas de story pour ce fichier, et c'est délibéré** : il ne rend rien seul.
 * Ce qu'il garantit se vérifie dans les stories de `LineChart`, `BarChart` et
 * `DonutChart`, qui l'utilisent. Une story de remplissage donnerait l'illusion
 * d'une couverture sans rien tester de plus.
 *
 * Elle existe pour que le contrat d'accessibilité soit tenu **par
 * construction** plutôt que répété — et oublié une fois sur cinq. Tout
 * graphique du système passe par elle, et en hérite :
 *
 * 1. **Le graphique est masqué, le tableau EST le contenu.** Un SVG de
 *    données ne se lit pas : on ne peut ni comparer deux valeurs, ni en
 *    retrouver une, ni copier quoi que ce soit. Le `aria-label` donne le
 *    résumé, le tableau donne la donnée — et il réutilise `Table`, donc ses
 *    en-têtes de ligne et de colonne.
 * 2. **La légende arrive AVANT le graphique.** Elle en est la clé de
 *    lecture ; en dessous, elle arrive trop tard.
 * 3. **Trois canaux par série**, jamais la couleur seule (WCAG 1.4.1).
 * 4. **Aucune animation** (WCAG 2.3.3).
 *
 * Le tableau est replié dans un `details` par défaut : présent dans le
 * document et lu, sans occuper la place.
 */
export function ChartFrame<T>({
  caption,
  summary,
  series,
  data,
  columns,
  getRowKey,
  rowHeaderKey,
  children,
  height = 280,
  hideLegend = false,
  legendStyle = "trait",
  tableCollapsed = true,
  className,
}: ChartFrameProps<T>) {
  const uid = useId().replace(/:/g, "");

  // ── Survol : l'infobulle et l'emphase ────────────────────────────────────
  //
  // WCAG 1.4.13 — un contenu qui apparaît au survol doit pouvoir être ÉCARTÉ
  // sans déplacer le pointeur. Recharts ne le prévoit pas : son infobulle
  // suit la souris et rien ne la referme. Échap la retire donc ici, et elle
  // ne revient qu'après être sorti puis rentré dans le graphique — c'est le
  // comportement attendu par le critère, pas une bascule permanente.
  const [survol, setSurvol] = useState(false);
  const [ecartee, setEcartee] = useState(false);
  const [indexActif, setIndexActif] = useState<number | null>(null);

  useEffect(() => {
    if (!survol || ecartee) return;
    const auClavier = (e: KeyboardEvent) => {
      if (e.key === "Escape") setEcartee(true);
    };
    document.addEventListener("keydown", auClavier);
    return () => document.removeEventListener("keydown", auClavier);
  }, [survol, ecartee]);

  const tableau = (
    <Table
      caption={caption}
      captionHidden
      columns={columns}
      rows={data}
      getRowKey={getRowKey}
      rowHeaderKey={rowHeaderKey}
      density="compact"
    />
  );

  return (
    <figure className={cn("m-0 flex flex-col gap-4", className)}>
      <figcaption className="text-sm font-medium text-foreground">
        {caption}
      </figcaption>

      {!hideLegend && <ChartLegend series={series} style={legendStyle} />}

      <div
        role="img"
        aria-label={`${summary} Les valeurs exactes sont dans le tableau qui suit.`}
        style={{ height }}
        className="w-full"
      >
        {/*
          Le SVG est masqué, et ce n'est pas une redondance avec le `role="img"`
          du parent. Recharts pose `role="img"` sur CHAQUE secteur et chaque
          tracé, sans nom accessible : axe y voit autant d'images sans
          alternative. Le parent porte le nom, le tableau porte la donnée.
        */}
        <div
          aria-hidden="true"
          className="h-full w-full"
          onMouseEnter={() => setSurvol(true)}
          onMouseLeave={() => {
            setSurvol(false);
            setEcartee(false);
            setIndexActif(null);
          }}
        >
          {children({
            idTrames: uid,
            infobulleActive: survol && !ecartee,
            indexActif,
            surSurvol: (etat) => setIndexActif(etat?.activeTooltipIndex ?? null),
          })}
        </div>
      </div>

      {tableCollapsed ? (
        <details className="group">
          <summary
            className={cn(
              "cursor-pointer list-none text-sm font-medium text-[var(--secondary)]",
              "min-h-11 inline-flex items-center gap-1.5 rounded-[var(--radius)]",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]"
            )}
          >
            <svg
              aria-hidden="true"
              viewBox="0 0 12 12"
              className="size-3 transition-transform group-open:rotate-90 motion-reduce:transition-none"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M4.5 2.5 8 6l-3.5 3.5" />
            </svg>
            Voir les données
          </summary>
          <div className="pt-3">{tableau}</div>
        </details>
      ) : (
        tableau
      )}
    </figure>
  );
}

// ─── Légende ──────────────────────────────────────────────────────────────────

export interface ChartLegendProps {
  series: ChartSerie[];
  /** `trait` pour les courbes, `aplat` pour les barres et les parts. */
  style?: "trait" | "aplat";
  className?: string;
}

/**
 * Légende d'un graphique.
 *
 * Chaque entrée montre les canaux tels qu'on les reconnaîtra dans le
 * graphique — la couleur et, pour les courbes, le tracé. Une légende qui
 * montrerait autre chose que le graphique ne sert à rien.
 *
 * Le nom du canal est aussi écrit en `sr-only`. Sans lui, la légende lue à
 * voix haute donne une liste de noms sans clé de lecture.
 */
export function ChartLegend({ series, style = "trait", className }: ChartLegendProps) {
  return (
    <ul className={cn("flex flex-wrap gap-x-5 gap-y-2 list-none m-0 p-0", className)}>
      {series.map((s, i) => {
        const v = styleSerie(i);
        const c = couleurSerie(i);
        return (
          <li key={s.key} className="inline-flex items-center gap-2 text-sm">
            <svg
              aria-hidden="true"
              focusable="false"
              viewBox={style === "trait" ? "0 0 28 12" : "0 0 36 14"}
              className={cn("shrink-0", style === "trait" ? "h-3 w-7" : "h-3.5 w-9")}
              fill="none"
            >
              {style === "trait" ? (
                <>
                  <line x1="0" y1="6" x2="28" y2="6" stroke={c} strokeWidth="2" strokeDasharray={v.trait} />
                  <circle cx="14" cy="6" r="3.5" fill={c} />
                </>
              ) : (
                // Pastille pleine. Elle montre exactement ce que montre le
                // graphique — c'est toute la fonction d'une légende.
                <rect x="0" y="0" width="36" height="14" rx="3" fill={c} />
              )}
            </svg>
            <span className="text-foreground">{s.label}</span>
            <span className="sr-only">
              ({style === "trait" ? v.nom : "aplat"})
            </span>
          </li>
        );
      })}
    </ul>
  );
}

import { type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Skeleton } from "@registry/aikoz/skeleton/skeleton";

// ─── Types ────────────────────────────────────────────────────────────────────

export type SortDirection = "asc" | "desc";

export interface TableSort {
  key: string;
  direction: SortDirection;
}

export interface TableColumn<T> {
  key: string;
  /** En-tête de colonne. Court : il est relu à chaque cellule par un
   *  lecteur d'écran en mode tableau. */
  header: string;
  /** Rendu de la cellule. Par défaut, la valeur brute de `row[key]`. */
  cell?: (row: T) => ReactNode;
  /**
   * Colonne de nombres : alignée à droite et en chiffres tabulaires, pour
   * que les unités s'empilent et que la comparaison verticale soit possible.
   */
  numeric?: boolean;
  /** Rend l'en-tête cliquable et pose `aria-sort`. */
  sortable?: boolean;
  /** Largeur CSS imposée — `"12rem"`, `"25%"`. */
  width?: string;
}

export interface TableProps<T> {
  /**
   * Ce que le tableau contient — **obligatoire**. C'est son nom accessible,
   * et c'est ce qui permet de savoir dans quel tableau on est quand une page
   * en porte plusieurs. Rendu en `<caption>`, donc lié nativement, sans
   * `aria-label` à maintenir en double.
   */
  caption: string;
  /** Masque la légende visuellement. Elle reste lue. */
  captionHidden?: boolean;
  columns: TableColumn<T>[];
  rows: T[];
  getRowKey: (row: T, index: number) => string;
  /**
   * Colonne qui NOMME la ligne — le libellé d'agence, le nom d'aéroport.
   * Elle est rendue en `<th scope="row">`, ce qui fait annoncer « Amsterdam,
   * taux de réponse, 94 % » au lieu de « 94 % » tout court quand on navigue
   * de cellule en cellule.
   */
  rowHeaderKey?: string;
  sort?: TableSort;
  onSortChange?: (sort: TableSort) => void;
  /** Affiche des lignes d'attente à la place des données. */
  loading?: boolean;
  /** Nombre de lignes d'attente. */
  loadingRows?: number;
  /** Rendu quand `rows` est vide — un `EmptyState`, en général. */
  empty?: ReactNode;
  density?: "compact" | "default";
  className?: string;
}

// ─── Sous-éléments ────────────────────────────────────────────────────────────

/** Deux chevrons superposés : l'actif est plein, l'autre effacé. La direction
 *  ne tient donc pas à la seule couleur — la FORME diffère. */
function Fleche({ direction }: { direction?: SortDirection }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 10 12"
      className="size-2.5 shrink-0"
      fill="currentColor"
    >
      <path d="M5 0.5 8 4H2z" opacity={direction === "asc" ? 1 : 0.3} />
      <path d="M5 11.5 2 8h6z" opacity={direction === "desc" ? 1 : 0.3} />
    </svg>
  );
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Tableau de données.
 *
 * Un vrai `<table>`, pas une grille CSS de `div`. Ce n'est pas une question
 * de goût : les balises de tableau portent des RELATIONS que rien ne remplace.
 * Un lecteur d'écran en mode tableau annonce, à chaque déplacement, l'en-tête
 * de colonne et l'en-tête de ligne de la cellule où il arrive — « Amsterdam,
 * taux de réponse, 94 % ». Une grille de `div` ne donne que « 94 % », et
 * l'utilisateur doit compter les colonnes de tête.
 *
 * Trois choses que ce composant fait et qu'on oublie presque toujours :
 *
 * 1. **`<caption>` plutôt qu'`aria-label`.** La légende est visible par
 *    défaut, liée nativement, et ne peut pas se désynchroniser d'un titre
 *    voisin. `captionHidden` la masque quand la mise en page l'exige.
 * 2. **Le conteneur qui défile est focusable.** Un tableau plus large que son
 *    cadre défile horizontalement ; sans `tabIndex={0}` sur le conteneur, la
 *    partie hors champ est inatteignable au clavier — on ne peut pas faire
 *    défiler ce sur quoi on ne peut pas se poser. Il porte `role="region"` et
 *    un nom, sinon ce nouvel arrêt de tabulation serait muet.
 * 3. **Le tri s'annonce par `aria-sort` sur le `<th>`**, pas par une icône.
 *    Le bouton reste dans l'en-tête plutôt que d'être l'en-tête lui-même :
 *    un `<th>` cliquable sans bouton n'est ni focusable ni actionnable au
 *    clavier.
 */
export function Table<T>({
  caption,
  captionHidden = false,
  columns,
  rows,
  getRowKey,
  rowHeaderKey,
  sort,
  onSortChange,
  loading = false,
  loadingRows = 5,
  empty,
  density = "default",
  className,
}: TableProps<T>) {
  const cellule = density === "compact" ? "px-3 py-2" : "px-4 py-3";

  function trier(key: string) {
    const direction: SortDirection =
      sort?.key === key && sort.direction === "asc" ? "desc" : "asc";
    onSortChange?.({ key, direction });
  }

  const vide = !loading && rows.length === 0;

  return (
    <div
      // `role="region"` + nom + `tabIndex` : les trois vont ensemble. Sans le
      // nom, un lecteur d'écran annonce « région » sans dire laquelle ; sans
      // `tabIndex`, le débordement horizontal est inatteignable au clavier.
      role="region"
      aria-label={caption}
      tabIndex={0}
      // `aria-busy` porté UNE fois par le conteneur, pas par chaque squelette :
      // c'est le tableau qui charge, pas quatorze rectangles.
      aria-busy={loading || undefined}
      className={cn(
        "w-full overflow-x-auto rounded-[var(--radius)] border border-border bg-card",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
        className
      )}
    >
      <table className="w-full border-collapse text-sm">
        <caption
          className={cn(
            "text-left text-sm text-muted-foreground",
            captionHidden ? "sr-only" : cellule
          )}
        >
          {caption}
        </caption>

        <thead>
          <tr className="border-b border-border">
            {columns.map((c) => {
              const actif = sort?.key === c.key;
              return (
                <th
                  key={c.key}
                  scope="col"
                  // `aria-sort` ne va que sur la colonne triée : le poser à
                  // « none » partout ferait annoncer « non trié » sur chaque
                  // en-tête, à chaque parcours.
                  aria-sort={
                    actif
                      ? sort.direction === "asc"
                        ? "ascending"
                        : "descending"
                      : undefined
                  }
                  style={c.width ? { width: c.width } : undefined}
                  className={cn(
                    cellule,
                    "font-semibold text-foreground",
                    c.numeric ? "text-right" : "text-left"
                  )}
                >
                  {c.sortable && onSortChange ? (
                    <button
                      type="button"
                      onClick={() => trier(c.key)}
                      className={cn(
                        "inline-flex items-center gap-1.5 min-h-6 rounded-[calc(var(--radius)/2)]",
                        "font-semibold hover:text-[var(--secondary)]",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                        c.numeric && "flex-row-reverse"
                      )}
                    >
                      {c.header}
                      <Fleche direction={actif ? sort.direction : undefined} />
                    </button>
                  ) : (
                    c.header
                  )}
                </th>
              );
            })}
          </tr>
        </thead>

        <tbody>
          {loading &&
            Array.from({ length: loadingRows }, (_, i) => (
              <tr key={`attente-${i}`} className="border-b border-border last:border-0">
                {columns.map((c) => (
                  <td key={c.key} className={cellule}>
                    <Skeleton shape="text" className={c.numeric ? "w-12 ml-auto" : "w-4/5"} />
                  </td>
                ))}
              </tr>
            ))}

          {vide && (
            <tr>
              {/* `colSpan` sur toute la largeur : une cellule vide par colonne
                  ferait annoncer autant de cellules vides. */}
              <td colSpan={columns.length} className="p-0">
                {empty}
              </td>
            </tr>
          )}

          {!loading &&
            rows.map((row, i) => (
              <tr
                key={getRowKey(row, i)}
                className="border-b border-border last:border-0 hover:bg-[var(--surface-hover)]"
              >
                {columns.map((c) => {
                  const contenu = c.cell
                    ? c.cell(row)
                    : ((row as Record<string, unknown>)[c.key] as ReactNode);
                  const classes = cn(
                    cellule,
                    // Chiffres tabulaires : sans eux, les colonnes de nombres
                    // ne s'alignent pas verticalement et la comparaison d'une
                    // ligne à l'autre demande de relire chiffre par chiffre.
                    c.numeric ? "text-right tabular-nums" : "text-left"
                  );
                  return c.key === rowHeaderKey ? (
                    <th
                      key={c.key}
                      scope="row"
                      className={cn(classes, "font-medium text-foreground")}
                    >
                      {contenu}
                    </th>
                  ) : (
                    <td key={c.key} className={cn(classes, "text-foreground")}>
                      {contenu}
                    </td>
                  );
                })}
              </tr>
            ))}
        </tbody>
      </table>
    </div>
  );
}

import { type HTMLAttributes } from "react";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface SkeletonProps extends HTMLAttributes<HTMLDivElement> {
  /** Forme du bloc. `text` prend la hauteur d'une ligne, `circle` un rond. */
  shape?: "block" | "text" | "circle";
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Bloc d'attente.
 *
 * **Il est intégralement invisible aux technologies d'assistance**, et ce
 * n'est pas un oubli : annoncer « rectangle gris » quatorze fois ne renseigne
 * personne. C'est au CONTENEUR de dire qu'un chargement est en cours, une
 * fois, par `aria-busy="true"` — et de dire ce qui a chargé une fois fini,
 * par une région live. Un squelette qui parle est un squelette qui bavarde.
 *
 * L'animation est coupée par `motion-reduce` : une pulsation permanente sur
 * toute une page déclenche des malaises chez les personnes sensibles au
 * mouvement (WCAG 2.3.3). Sans elle le bloc reste parfaitement lisible — il
 * n'a jamais porté d'information dans son mouvement.
 *
 * `--track` et non `--muted` : en thème sombre ce dernier vaut exactement
 * `--card`, le squelette y serait strictement invisible. C'est le même piège
 * que la piste de `ProgressBar`.
 */
export function Skeleton({ shape = "block", className, ...props }: SkeletonProps) {
  return (
    <div
      aria-hidden="true"
      className={cn(
        "bg-[var(--track)] motion-safe:animate-pulse",
        shape === "circle" && "rounded-full aspect-square",
        shape === "text" && "h-4 rounded-[calc(var(--radius)/2)]",
        shape === "block" && "rounded-[var(--radius)]",
        className
      )}
      {...props}
    />
  );
}

export interface SkeletonTextProps {
  /** Nombre de lignes. */
  lines?: number;
  className?: string;
}

/**
 * Paragraphe d'attente. La dernière ligne est plus courte — un bloc de
 * lignes toutes égales ne ressemble à aucun texte réel, et l'œil met plus
 * longtemps à comprendre qu'il regarde une attente.
 */
export function SkeletonText({ lines = 3, className }: SkeletonTextProps) {
  return (
    <div className={cn("flex flex-col gap-2", className)}>
      {Array.from({ length: lines }, (_, i) => (
        <Skeleton key={i} shape="text" className={i === lines - 1 ? "w-3/5" : "w-full"} />
      ))}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
